"use strict";

const E = QuestEngine;
const CATALOG = PERIODIC_ELEMENTS;
const bySymbol = Object.fromEntries(CATALOG.map(element => [element.symbol, element]));
const paths = {
  gift:'<path d="M3 9h18v5H3zm2 5v7h14v-7M12 9v12M12 9C4 9 4 2 8 3c3 0 4 6 4 6Zm0 0c8 0 8-7 4-6-3 0-4 6-4 6Z"/>',
  world:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18"/>',
  flask:'<path d="M9 3h6m-5 0v7L4 19q-1 2 2 2h12q3 0 2-2l-6-9V3M7 15h10"/>',
  grid:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',
  trophy:'<path d="M7 3h10v7a5 5 0 0 1-10 0zm5 12v6m-4 0h8M7 5H3v3a5 5 0 0 0 5 5m9-8h4v3a5 5 0 0 1-5 5"/>',
  spark:'<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"/>',
  sound:'<path d="m10 5-4 4H3v6h3l4 4zM15 8a6 6 0 0 1 0 8m4-11a10 10 0 0 1 0 14"/>',
  mute:'<path d="m10 5-4 4H3v6h3l4 4zM16 9l6 6m0-6-6 6"/>',
  help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 4 3c-1 0-1 1-1 2m0 3h.01"/>',
  arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
  check:'<path d="m5 12 4 4L19 6"/>',
  repeat:'<path d="M20 7A9 9 0 0 0 5 5L2 8m0-5v5h5M4 17a9 9 0 0 0 15 2l3-3m0 5v-5h-5"/>',
  pair:'<path d="M4 5h5v5H4zm11 9h5v5h-5zM9 8c9 0-3 8 6 8M4 19h5M15 5h5"/>',
  atom:'<circle cx="12" cy="12" r="2"/><ellipse cx="12" cy="12" rx="11" ry="4"/><ellipse cx="12" cy="12" rx="11" ry="4" transform="rotate(60 12 12)"/><ellipse cx="12" cy="12" rx="11" ry="4" transform="rotate(120 12 12)"/>',
  type:'<path d="M4 5h16M12 5v15M8 20h8M4 5v3m16-3v3"/>',
  water:'<path d="M12 2C9 7 4 11 4 15a8 8 0 0 0 16 0c0-4-5-8-8-13zM8 15a4 4 0 0 0 4 4"/>',
  air:'<path d="M3 8h12a3 3 0 1 0-3-3M3 12h17a3 3 0 1 1-3 3M3 17h7a2 2 0 1 1-2 2"/>',
  leaf:'<path d="M20 3C5 1 0 15 7 20S23 17 20 3ZM4 22 17 7"/>',
  pencil:'<path d="m4 16 12-12 4 4L8 20l-5 1zm10-10 4 4"/>',
  chip:'<rect x="6" y="6" width="12" height="12" rx="2"/><path d="M9 6V2m6 4V2M9 18v4m6-4v4M6 9H2m4 6H2m16-6h4m-4 6h4"/>',
  salt:'<path d="m7 9-2 12h14L17 9zm0 0V5h10v4M9 5V3h6v2M9 13h.1m5 3h.1"/>',
  bone:'<path d="M8 7a3 3 0 1 0-4 4l9 7a3 3 0 1 0 4 2 3 3 0 1 0 3-4l-9-8a3 3 0 1 0-3-1z"/>',
  lamp:'<path d="M9 21h6m-6-4h6v-2a7 7 0 1 0-6 0zM9 9l3 3 3-3m-3 3v5"/>',
  battery:'<rect x="3" y="6" width="17" height="12" rx="2"/><path d="M20 10h2v4h-2M7 9v6m-3-3h6m4 0h3"/>',
  glass:'<path d="M5 3h14l-2 18H7zM6 9h12"/>',
  metal:'<path d="m3 15 5-9h9l4 9-5 5H8zm0 0h18M8 6l2 9 6 5m1-14-3 9"/>',
  balloon:'<ellipse cx="12" cy="9" rx="7" ry="8"/><path d="m12 17-2 3h4zm0 3v3M8 7q0-3 3-3"/>',
  sun:'<circle cx="12" cy="12" r="5"/><path d="M12 1v2m0 18v2M1 12h2m18 0h2M4 4l2 2m12 12 2 2M20 4l-2 2M6 18l-2 2"/>',
  earth:'<path d="m2 20 6-12 4 6 4-10 6 16zM6 12l2 3 2-3m4-4 2 3 2-3"/>'
};
const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name] || paths.atom}</svg>`;
const esc = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const FAMILY_CLASSES = {'Неметаллы':'family-nonmetal','Благородные газы':'family-noble','Галогены':'family-halogen','Щёлочные металлы':'family-alkali','Щёлочноземельные металлы':'family-earth','Переходные металлы':'family-transition','Лантаноиды':'family-lanthanide','Актиноиды':'family-actinide','Полуметаллы':'family-metalloid','Металлы':'family-metal'};
const page = document.getElementById('page-content');
const dialog = document.getElementById('game-dialog');
const game = document.getElementById('game-content');
const rewardDialog = document.getElementById('reward-dialog');
const rewardContent = document.getElementById('reward-content');
const blockedStores = new Set();
const STATS_KEY = 'element-lab-v1';
const JOURNEY_KEY = 'element-quest-journey-v1';
function readStore(key, clean, fresh) {
  try { const raw=localStorage.getItem(key);return raw?clean(JSON.parse(raw),Object.keys(bySymbol)):fresh(); }
  catch { blockedStores.add(key);return fresh(); }
}
const stats = readStore(STATS_KEY,E.cleanStats,E.freshStats);
const journey = readStore(JOURNEY_KEY,E.cleanJourney,E.freshJourney);
let currentView = ['learn','practice','collection','treasure','progress'].includes(location.hash.slice(1))?location.hash.slice(1):'learn';
let collectionMode = 'table';
let collectionScope = 118;
let activeReward = null;
let lastOscillator = null;
let session = null;
let speechToken = 0;
let audioContext = null;
let toastTimer = 0;
let returnFocus = null;
const BADGES = {first:{name:'Первое открытие',icon:'spark',text:'Заверши экспедицию'},pairs:{name:'Связи найдены',icon:'pair',text:'Собери все четыре пары'},builder:{name:'Архитектор молекул',icon:'atom',text:'Верно собери состав молекулы'},explorer:{name:'Четыре горизонта',icon:'world',text:'Заверши четыре экспедиции'}};
const MODES = [
  {id:'pairs',name:'Соедини пары',text:'Символы и названия ищут друг друга',icon:'pair',color:'cyan'},
  {id:'build',name:'Собери молекулу',text:'Разберись, что означают индексы',icon:'atom',color:'mint'},
  {id:'application',name:'Химия вокруг',text:'От карандаша до аккумулятора',icon:'leaf',color:'gold'},
  {id:'table',name:'Найди в таблице',text:'Исследуй адреса элементов',icon:'grid',color:'violet'},
  {id:'audio',name:'Узнай на слух',text:'Послушай название и вспомни символ',icon:'sound',color:'cyan'},
  {id:'typing',name:'Вспомни символ',text:'Напиши ответ без вариантов',icon:'type',color:'gold'}
];
function save() {
  for(const [key,value] of [[STATS_KEY,stats],[JOURNEY_KEY,journey]]) {
    if(blockedStores.has(key))continue;
    try{localStorage.setItem(key,JSON.stringify(value));}catch{blockedStores.add(key);toast('Прогресс доступен в этом сеансе, но браузер не смог его сохранить.');}
  }
  renderHeader();
}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.hidden=true;},4500);}
function mascot(mood='welcome',extra='') {
  return `<span class="rick-emotion emotion-${mood}" aria-hidden="true">${{welcome:'✦',thinking:'?',success:'★',support:'♡',speaking:'♪'}[mood]||'✦'}</span>`;
}

function stars(count){return `<span class="stars" aria-label="${count} из 3 звёзд">${[1,2,3].map(n=>`<span class="${n<=count?'earned':''}">★</span>`).join('')}</span>`;}
function mastery(symbol){return stats.elements[symbol]?.wrong?0:E.mastery(journey,symbol);}
function masteryDots(symbol){const level=mastery(symbol);return `<span class="mastery" aria-label="${level} из 3 ступеней">${[1,2,3].map(i=>`<i class="${i<=level?'lit':''}"></i>`).join('')}</span>`;}
function dueElements(){return CATALOG.filter(element=>E.isDue(stats,element.symbol));}

function activePool(){const tried=CATALOG.filter(element=>stats.elements[element.symbol]?.attempts);return tried.length>=4?tried.map(element=>element.symbol):E.MISSIONS[0].symbols;}

function warning(){return blockedStores.size?'<div class="storage-warning" role="status">Не удалось прочитать сохранённую историю. Сейчас можно играть; новые результаты доступны до закрытия страницы.</div>':'';}
function renderHeader(){
  const level=Math.floor(stats.xp/100)+1,progress=stats.xp%100;
  document.querySelector('.xp-counter').innerHTML=`<span class="level-number">${level}</span><span><b id="header-xp">${stats.xp}</b> XP<span class="level-track"><i style="width:${progress}%"></i></span></span>`;
  document.querySelector('.xp-counter').setAttribute('aria-label',`Уровень ${level}. ${100-progress} XP до следующего`);
  document.getElementById('crystal-balance').textContent=`◆ ${journey.treasure.crystals}`;
  document.querySelectorAll('[data-view]').forEach(button=>{button.classList.toggle('active',button.dataset.view===currentView);if(button.dataset.view===currentView)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');});
  for(const [id,on,label] of [['sound-toggle',journey.sound,'сигналы ответов'],['voice-toggle',journey.speech,'озвучивание']]){const button=document.getElementById(id);button.innerHTML=icon(on?'sound':'mute');button.setAttribute('aria-pressed',String(on));button.setAttribute('aria-label',`${on?'Выключить':'Включить'} ${label}`);button.title=button.getAttribute('aria-label');}
  document.body.dataset.theme=journey.treasure.equipped;document.body.dataset.motion=journey.motion?'reduce':'full';document.getElementById('motion-toggle').checked=journey.motion;
}

function renderPage(){
  renderHeader();document.body.dataset.view=currentView;
  ({learn:renderWorld,practice:renderPractice,collection:renderCollection,treasure:renderTreasure,progress:renderProgress})[currentView]();
}

function renderWorld(){
  const next=E.MISSIONS.find(m=>!journey.missions[m.id]?.completed)||E.MISSIONS.find(m=>(journey.missions[m.id]?.stars||0)<3)||E.MISSIONS[0];
  const daily=journey.daily[E.dayKey()]||{lessons:0,pairs:0,models:0};
  const goals=[{name:'Одна экспедиция',count:daily.lessons,target:1,icon:'world'},{name:'Три пары',count:daily.pairs,target:3,icon:'pair'},{name:'Одна молекула',count:daily.models,target:1,icon:'atom'}];
  const ready=E.CHESTS.map(c=>E.chestStatus(journey,c.id)).find(c=>c.eligible&&!c.claimed);
  const featured=ready||E.CHESTS.map(c=>E.chestStatus(journey,c.id)).find(c=>!c.claimed)||E.chestStatus(journey,'life');
  page.innerHTML=`${warning()}<div class="world-heading"><div><div class="eyebrow">Экспедиция с Риком</div><h1>Маленькие элементы.<br>Большие открытия!</h1></div><div class="quick-rules"><span><b>1</b> Изучи 5 элементов</span><span><b>2</b> Реши 8 заданий</span><span><b>3</b> Открой сундук</span></div></div>
  <div class="world-layout"><aside class="mentor-panel guide-scene"><div class="guide-caption"><span class="guide-name">Рик на связи</span><h2>Соберём твою<br>лабораторию?</h2><p>Каждый остров хранит новый экспонат.</p><button class="primary" data-action="mission" data-id="${next.id}">Начать экспедицию ${icon('arrow')}</button></div></aside>
  <section class="world-center" aria-label="Карта экспедиций"><div class="world-map"><img class="world-art" src="assets/v2/world.png" alt="Четыре красочных острова экспедиции"><div class="map-shade"></div>${E.MISSIONS.map((mission,index)=>{const chest=E.chestStatus(journey,mission.id);return `<button class="map-node node-${mission.id} ${journey.missions[mission.id]?.completed?'completed':''} ${mission.id===next.id?'next':''}" style="--x:${mission.x}%;--y:${mission.y}%" data-action="mission" data-id="${mission.id}" aria-label="Экспедиция ${index+1}: ${mission.title}"><span class="node-disc">${journey.missions[mission.id]?.completed?icon('check'):index+1}</span><span class="node-label">${mission.title}${stars(journey.missions[mission.id]?.stars||0)}</span><span class="node-prize">${icon('gift')}${chest.claimed?'Получено':chest.eligible?'Сундук готов':'За первую звезду'}</span></button>`;}).join('')}<div class="map-caption">Выбери остров. Учись в своём темпе.</div></div>
  <div class="next-expedition panel"><span class="expedition-icon ${next.color}">${icon('world')}</span><div><span class="tiny muted">Следующая остановка</span><h2>${next.title}</h2><div class="symbol-strip">${next.symbols.map(symbol=>`<span>${symbol}</span>`).join('')}</div></div><button class="primary" data-action="mission" data-id="${next.id}">В путь ${icon('arrow')}</button></div></section>
  <aside class="mission-sidebar"><section class="panel daily-panel"><h2>${icon('spark')} Три открытия дня</h2>${goals.map(goal=>`<div class="daily-goal"><span class="goal-icon ${goal.count>=goal.target?'done':''}">${icon(goal.count>=goal.target?'check':goal.icon)}</span><div><b>${goal.name}</b><div class="progress-track"><span style="width:${Math.min(100,goal.count/goal.target*100)}%"></span></div></div><small>${Math.min(goal.count,goal.target)}/${goal.target}</small></div>`).join('')}<button class="daily-chest-button" data-action="chest" data-id="daily:${E.dayKey()}">${chestArt('small') }<span>Сундук дня<b>+20 ◆</b></span></button></section>
  <section class="panel prize-preview"><h2>${icon('gift')} ${ready?'Награда ждёт!':featured.claimed?'Все экспонаты собраны':'Следующее сокровище'}</h2>${chestArt('medium')}<b>${featured.artifact}</b><p>${ready?'Осталось открыть сундук.':featured.claimed?'Твоя полка полна открытий.':featured.condition}</p><button class="secondary" data-action="chest" data-id="${featured.id}">${ready?'Открыть сундук':'Посмотреть награду'}</button></section></aside></div>
  <div class="discovery-dock"><button data-view="collection"><span class="dock-table">118</span><span><b>Вся таблица элементов</b><small>От водорода до оганесона</small></span>${icon('arrow')}</button><button data-action="review" ${dueElements().length?'':'disabled'}>${icon('repeat')}<span><b>Освежить в памяти</b><small>${dueElements().length?`На повторение: ${dueElements().length}`:'Повторения появятся после занятий'}</small></span>${icon('arrow')}</button></div>
  <div class="section-heading"><h2>Играй по-своему</h2><button class="text-button" data-view="practice">Все режимы ${icon('arrow')}</button></div><div class="quick-practice">${MODES.slice(0,3).map(modeCard).join('')}</div>`;
}

function modeCard(mode){const art=mode.id==='audio'?'audio':mode.id==='table'?'gallery':mode.id==='application'?'gallery':'lab';return `<button class="mode-card scenic-mode mode-${mode.id}" data-action="practice" data-mode="${mode.id}" style="--mode-art:url('assets/v3/${art}-scene.png')"><span class="mode-card-picture"></span><span class="mode-icon ${mode.color}">${icon(mode.icon)}</span><span class="mode-copy"><strong>${mode.name}</strong><small>${mode.text}</small></span><span class="mode-arrow">›</span></button>`;}

function renderPractice(){page.innerHTML=`${warning()}<section class="page-scene-intro intro-lab"><div><span class="eyebrow">Рик приготовил шесть опытов для ума</span><h1>Твоя лаборатория<br>открытий</h1><p>Выбирай действие. Узнавай новое. Собирай награды.</p><div class="scene-tags"><span>Без таймера</span><span>Можно ошибаться</span><span>Прогресс сохраняется</span></div></div></section><div class="practice-grid">${MODES.map(modeCard).join('')}</div>`;}

function tile(element){return `<span class="element-tile ${element.color}"><small>${element.number}</small><strong>${element.symbol}</strong></span>`;}
function collectionCard(element){return `<button class="collection-card" data-action="inspect" data-symbol="${element.symbol}">${tile({...element,color:element.color||'blue'})}<h3>${element.name}</h3><span class="tiny muted">${element.examples?.[0]?.title||element.family}</span>${masteryDots(element.symbol)}${stats.elements[element.symbol]?.wrong?'<span class="needs-review">Повторить</span>':''}</button>`;}

function periodicTable(action='inspect',selected=null,checked=false,target=null){
  const entries=CATALOG;
  return `<div class="table-scroll complete-table-scroll" tabindex="0" aria-label="Полная периодическая таблица, 118 элементов"><div class="periodic-table complete-table">${Array.from({length:18},(_,i)=>`<span class="group-number" style="grid-column:${i+1};grid-row:1;--col:${i+1}">${i+1}</span>`).join('')}
  <span class="series-slot" style="grid-column:3;grid-row:7">57–71</span><span class="series-slot" style="grid-column:3;grid-row:8">89–103</span><span class="series-label" style="grid-column:1 / 3;grid-row:10">Лантаноиды</span><span class="series-label" style="grid-column:1 / 3;grid-row:11">Актиноиды</span>
  ${entries.map(element=>{const column=element.series==='lanthanide'?element.number-54:element.series==='actinide'?element.number-86:element.group;const row=element.series==='lanthanide'?10:element.series==='actinide'?11:element.period+1;return `<button class="periodic-cell ${FAMILY_CLASSES[element.family]||'family-metal'} ${selected===element.symbol?'selected':''} ${checked&&target===element.symbol?'correct':''} ${checked&&selected===element.symbol&&target!==selected?'wrong':''} ${stats.elements[element.symbol]?.attempts?'discovered':''}" style="grid-column:${column};grid-row:${row};--col:${column}" data-action="${action}" data-symbol="${element.symbol}" aria-label="${action==='inspect'?element.name:element.symbol}, атомный номер ${element.number}" ${checked?'disabled':''}><small>${element.number}</small><strong>${element.symbol}</strong>${action==='inspect'?`<span>${element.name}</span>`:''}</button>`;}).join('')}</div></div><p class="table-note">Все 118 элементов. Группы — сверху, два ряда внизу — лантаноиды и актиноиды. <span class="scroll-instruction">Листай таблицу вправо или выбери карточки.</span></p><div class="family-legend">${Object.entries(FAMILY_CLASSES).map(([name,color])=>`<span><i class="${color}"></i>${name}</span>`).join('')}</div>`;
}

function renderCollection(){page.innerHTML=`${warning()}<div class="catalog-layout"><aside class="catalog-guide"><div><span class="guide-name">Рик в музее элементов</span><h2>У каждого<br>элемента —<br>своя история</h2><p>Нажми ячейку.<br>Послушай имя.<br>Запомни символ.</p></div></aside><section class="catalog-main"><div class="catalog-head"><div><div class="eyebrow">От водорода до оганесона</div><h1>Вся таблица. Все 118.</h1><p>118 в справочнике · 20 подробно в первой главе</p></div><button class="primary" data-action="table-quiz" data-scope="118">Испытание 118 ${icon('arrow')}</button></div><div class="collection-toolbar"><input type="search" id="element-search" placeholder="Название, символ или номер" aria-label="Найти элемент"><div class="segmented"><button data-action="collection-mode" data-mode="table" aria-pressed="${collectionMode==='table'}">Таблица</button><button data-action="collection-mode" data-mode="cards" aria-pressed="${collectionMode==='cards'}">Карточки</button></div><span class="tiny muted" id="collection-count">118 элементов</span></div><div id="collection-results">${collectionMode==='cards'?`<div class="collection-grid">${CATALOG.map(collectionCard).join('')}</div>`:`<section class="panel full-table-panel">${periodicTable()}</section>`}</div><div class="mastery-legend"><span>● Узнал</span><span>●● Закрепляю</span><span>●●● Вспомнил в другой день</span></div><p class="catalog-scope">Нажми любую ячейку: справочные сведения и тренировка имени/символа доступны для всех 118. Семейства сверхтяжёлых показаны по положению в таблице; многие свойства ещё изучают.</p></section></div>`;}

function renderProgress(){const complete=Object.values(journey.missions).filter(m=>m.completed).length;const remembered=CATALOG.filter(el=>mastery(el.symbol)===3).length;page.innerHTML=`${warning()}<div class="page-heading progress-heading"><div class="eyebrow">Твои настоящие результаты</div><h1>Твои открытия</h1><p>Опыт — за практику. Звёзды — за точность. Уверенность в памяти проверим после перерыва.</p></div><div class="stats-grid"><section class="panel stat">${icon('world')}<b>${complete}<small>/ 4</small></b><span>экспедиций завершено</span></section><section class="panel stat">${icon('spark')}<b>${stats.xp}</b><span>опыта исследователя</span></section><section class="panel stat">${icon('repeat')}<b>${remembered}<small>/ 118</small></b><span>вспомнил в другой день</span></section><section class="panel stat">${icon('check')}<b>${stats.attempts?Math.round(stats.correct/stats.attempts*100):0}%</b><span>${stats.correct} верных из ${stats.attempts} ответов</span></section></div><h2 class="section-title">Сувениры из экспедиции</h2><div class="achievements">${Object.entries(BADGES).map(([id,badge])=>`<section class="panel achievement ${journey.badges.includes(id)?'unlocked':''}"><span class="achievement-medal">${icon(badge.icon)}</span><div><h3>${badge.name}</h3><p>${badge.text}</p><span class="tiny">${journey.badges.includes(id)?'Получено':'Ещё впереди'}</span></div></section>`).join('')}</div><div class="section-heading"><h2>Твоя карта открытий</h2></div><div class="mission-results">${E.MISSIONS.map(mission=>`<button class="panel mission-result" data-action="mission" data-id="${mission.id}"><span class="mode-icon ${mission.color}">${icon('world')}</span><span><b>${mission.title}</b><small>${journey.missions[mission.id]?.completed?`Лучший результат: ${journey.missions[mission.id].best}%`:'Первое путешествие впереди'}</small></span>${stars(journey.missions[mission.id]?.stars||0)}</button>`).join('')}</div><div class="review-summary panel"><div><h2>Повторение по памяти</h2><p>${dueElements().length?`Элементов на повторение: ${dueElements().length}.`:'Сейчас нет срочных повторений. Возвращайся после перерыва.'}</p></div><button class="secondary" data-action="review" ${dueElements().length?'':'disabled'}>Повторить ${icon('repeat')}</button></div>`;}
function startSession({pool,mode='mixed',mission=null,learn=false,inspect=false,recipes=null,focus=false}){
  cancelSpeech();returnFocus=document.activeElement;
  const count=focus?3:mode==='review'?Math.min(8,Math.max(pool.length,3)):8;
  session={pool,mode,mission,inspect,phase:learn?'learn':mode==='pairs'?'pairs':mode==='build'?'build':'question',learnIndex:0,index:0,questions:E.questionPlan(pool,mode==='review'?'mixed':mode,count,journey.speech&&Boolean(russianVoice())).map((q,i)=>focus?{...q,kind:['symbol','name','typing'][i]}:q.kind==='application'&&!bySymbol[q.symbol].application?{...q,kind:'name'}:q),baseTotal:count,baseCorrect:0,correct:0,xp:0,checked:false,selected:null,heard:false,assisted:false,mistakes:new Set(),resolved:new Set(),retryCount:0,streak:0,atoms:[],recipes:recipes||E.shuffle(E.RECIPES),failedRecipes:new Set(),matched:new Set(),failedPairs:new Set(),left:null,right:null,badges:[],finished:false};
  if(mode==='pairs'){session.pairPool=E.shuffle(pool).slice(0,4);session.rightOrder=E.shuffle(session.pairPool);session.baseTotal=session.pairPool.length;}
  if(mode==='review'){const supported=new Set();session.questions=session.questions.map(q=>{if(stats.elements[q.symbol]?.wrong&&!supported.has(q.symbol)){supported.add(q.symbol);return {...q,kind:'symbol'};}return q;});}
  if(focus)session.focus=true;
  if(mode==='build')session.baseTotal=session.recipes.length;
  renderGame();if(!dialog.open)dialog.showModal();document.body.classList.add('modal-open');
}
function startMission(id){const mission=E.MISSIONS.find(item=>item.id===id);if(mission)startSession({pool:mission.symbols,mission,learn:true});}
function startPractice(mode){let pool=mode==='table'?ELEMENTS.map(el=>el.symbol):activePool();if(mode==='application')pool=pool.filter(symbol=>bySymbol[symbol].application);startSession({pool:pool.length?pool:E.MISSIONS[0].symbols,mode});}

function startReview(pool=dueElements().map(el=>el.symbol)){if(!pool.length){toast('Сейчас нет элементов для повторения.');return;}startSession({pool,mode:'review'});}
function closeGame(){cancelSpeech();dialog.close();session=null;renderPage();if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});}
function sessionTitle(){if(session.customTitle)return session.customTitle;return session.inspect||session.focus?bySymbol[session.pool[0]].name:session.mission?.title||MODES.find(mode=>mode.id===session.mode)?.name||'Повторение открытий';}
function gameHeader(){const learn=session.phase==='learn';const total=learn?session.pool.length:session.phase==='pairs'?session.pairPool.length:session.phase==='build'?session.recipes.length:session.questions.length;const current=learn?session.learnIndex:session.phase==='pairs'?session.matched.size:session.index;return `<div class="game-header"><button class="close-button" data-action="close" aria-label="Закрыть занятие">×</button><div class="game-progress"><div><span>${sessionTitle()}</span><b>${learn?'Открытие':session.phase==='pairs'?'Пары':'Задание'} ${Math.min(current+(session.phase==='pairs'?0:1),total)} / ${total}</b></div><div class="progress-track"><span style="width:${current/total*100}%"></span></div></div><span class="session-xp">+${session.xp} XP</span></div>`;}
function mentorLine(text,mood='thinking'){return `<div class="mentor-line">${mascot(mood)}<p>${text}</p></div>`;}
function focusStep(){dialog.scrollTop=0;const title=game.querySelector('#game-title');if(title){title.tabIndex=-1;title.focus({preventScroll:true});}}
function renderLearn(){const el=bySymbol[session.pool[session.learnIndex]];if(!el.examples){renderReferenceCard(el);return;}const last=session.learnIndex===session.pool.length-1;game.innerHTML=`${gameHeader()}<div class="discovery-body"><div class="discovery-top"><div class="discovery-element">${tile(el)}<div><div class="eyebrow">Открытие № ${el.number}</div><h2 id="game-title">${el.name}</h2><p>${el.family} · ${el.state.toLowerCase()} при 20 °C</p><button class="listen-button" data-action="speak" data-symbol="${el.symbol}">${icon('sound')}${el.stress}</button><div class="audio-status" role="status"></div></div></div><div class="discovery-mentor">${mascot('welcome')}</div></div><div class="science-fact">${icon('atom')}<p>${el.fact}</p></div><h3 class="examples-title">Где ты с ним встречаешься</h3><div class="examples-grid">${el.examples.map(example=>`<article class="example-card"><div class="example-art art-${example.icon}">${icon(example.icon)}</div><h4>${example.title}</h4><p>${example.description}</p></article>`).join('')}</div><div class="discovery-note"><span>${el.cue}</span><button class="text-button" data-action="glossary">Мини-словарь</button><a href="${el.source}" target="_blank" rel="noopener noreferrer">Источник: RSC ${icon('arrow')}</a></div></div><div class="game-bottom">${session.inspect?'<p>Сначала знакомство — потом практика</p>':'<button class="text-button" data-action="skip-cards">Уже знаком? К заданиям</button>'}<button class="primary" data-action="next-card">${session.inspect?'Вернуться':last?'Проверить открытия':'Следующий элемент'} ${icon('arrow')}</button></div>`;decorateSession('lab','Ищи химию в знакомых вещах.');focusStep();}
function currentQuestion(){return session.questions[session.index];}
function answerOptions(question){
  if(question.choices)return question.choices;
  const element=bySymbol[question.symbol];
  if(question.kind==='application')question.choices=E.shuffle(element.application.options.map((text,index)=>({value:String(index),text})));
  else{
    const similar={H:['He'],He:['H'],C:['Ca','Cl'],Ca:['C','Cl'],Cl:['C','Ca'],N:['Na','Ne'],Na:['N','Ne'],Ne:['N','Na'],B:['Be'],Be:['B'],S:['Si'],Si:['S'],Al:['Ar'],Ar:['Al']};
    const neighbors=element.number<=20?ELEMENTS:CATALOG.filter(el=>el.period===element.period||el.group===element.group);
    const candidates=[...new Set([...E.shuffle(similar[question.symbol]||[]),...E.shuffle(session.pool),...E.shuffle(neighbors.map(el=>el.symbol))])].filter(symbol=>symbol!==question.symbol).slice(0,3);
    question.choices=E.shuffle([question.symbol,...candidates]).map(symbol=>({value:symbol,text:question.kind==='name'?bySymbol[symbol].name:symbol}));
  }
  return question.choices;
}
function renderQuestion(){const q=currentQuestion(),el=bySymbol[q.symbol];session.selected=null;session.checked=false;session.assisted=false;session.heard=false;let title='Какой символ у этого элемента?';let prompt=el.name;if(q.kind==='name'){title='Как называется этот элемент?';prompt=el.symbol;}if(q.kind==='application'){title='Химия в реальной жизни';prompt=el.application.question;}if(q.kind==='table'){title='Найди элемент в таблице';prompt=el.name;}if(q.kind==='audio'){title='Какой элемент ты слышишь?';prompt='';}
  const body=q.kind==='typing'?'<form id="answer-form"><input class="input-answer" id="symbol-input" aria-label="Химический символ" placeholder="?" autocomplete="off" autocapitalize="off" spellcheck="false" maxlength="3"><p class="input-hint">Латинские буквы. Первая — большая, вторая — маленькая.</p></form>':q.kind==='table'?periodicTable('answer-table'): `<div class="answer-grid ${q.kind==='application'?'application-options':''}">${answerOptions(q).map((option,index)=>`<button class="answer-option ${q.kind==='name'||q.kind==='application'?'word-option':''}" data-action="answer" data-value="${option.value}" ${q.kind==='audio'?'disabled':''}><small aria-hidden="true">${index+1}</small><span>${esc(option.text)}</span></button>`).join('')}</div>`;
  game.innerHTML=`${gameHeader()}<div class="game-body ${q.kind==='table'?'table-game':''}"><div class="question-meta"><span>${q.retry?'Вернёмся к недавней ошибке':q.kind==='application'?'Применяем знания':'Вспоминаем без карточки'}</span><span>${session.streak>=2?`${session.streak} подряд ✦`:''}</span></div><h2 id="game-title">${title}</h2>${q.kind==='audio'?`<div class="audio-question"><button class="audio-orb" data-action="question-audio" aria-label="Послушать элемент">${icon('sound')}<span class="audio-rings"></span></button><div class="waveform" aria-hidden="true"><i style="--bar:0"></i><i style="--bar:1"></i><i style="--bar:2"></i><i style="--bar:3"></i><i style="--bar:4"></i><i style="--bar:5"></i><i style="--bar:6"></i><i style="--bar:7"></i><i style="--bar:8"></i><i style="--bar:9"></i><i style="--bar:10"></i><i style="--bar:11"></i><i style="--bar:12"></i><i style="--bar:13"></i><i style="--bar:14"></i><i style="--bar:15"></i><i style="--bar:16"></i><i style="--bar:17"></i><i style="--bar:18"></i><i style="--bar:19"></i></div><p>Слушай → вспомни → выбери символ</p><div class="audio-status" role="status"></div><div class="audio-alternatives"><button class="text-button" data-action="toggle-voice">${journey.speech?'Выключить голос':'Включить голос'}</button><button class="text-button" data-action="audio-slow">Послушать медленнее</button><button class="text-button fallback-button" data-action="audio-fallback">Продолжить без звука</button></div></div>`:`<div class="question-prompt ${q.kind==='application'?'application-prompt':''}">${q.kind==='application'?`<span class="application-illustration">${icon(el.examples[0].icon)}</span>`:''}${prompt}</div>`}${body}<div id="feedback" role="status" aria-live="polite"></div><div id="hint-content"></div></div><div class="game-bottom"><button class="text-button" data-action="hint" ${q.kind==='audio'?'hidden':''}>${icon('help')}Нужна подсказка</button><button class="primary" id="check-answer" data-action="check" disabled>Проверить ${icon('check')}</button></div>`;
  const input=document.getElementById('symbol-input');if(input){input.addEventListener('input',()=>{session.selected=input.value.trim();document.getElementById('check-answer').disabled=!session.selected;});document.getElementById('answer-form').addEventListener('submit',event=>{event.preventDefault();checkAnswer();});}decorateSession(q.kind==='audio'?'audio':q.kind==='table'?'gallery':'lab',q.kind==='audio'?'Слушай внимательно. Можно повторить медленнее.':q.kind==='application'?'Теперь найди химию в реальной жизни.':q.retry?'Вернёмся к знакомому — получится лучше.':'Не спеши. Сначала попробуй вспомнить.');focusStep();
}
function selectAnswer(value){if(!session||session.phase!=='question'||session.checked)return;const q=currentQuestion();if(q.kind==='audio'&&!session.heard)return;session.selected=value;game.querySelectorAll('.answer-option,.periodic-cell').forEach(button=>{const selected=(button.dataset.value||button.dataset.symbol)===value;button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected));});document.getElementById('check-answer').disabled=false;}
function hint(){if(session.checked)return;const q=currentQuestion(),el=bySymbol[q.symbol];session.assisted=true;const text=q.kind==='application'?el.application.explanation:q.kind==='table'?`Ищи период ${el.period}${el.group?`, группу ${el.group}`:el.series==='lanthanide'?', ряд лантаноидов':', ряд актиноидов'}. Символ — ${el.symbol}.`:`${el.name} — ${el.symbol}. ${el.cue||'Запомни эту пару и попробуй снова без подсказки.'}`;document.getElementById('hint-content').innerHTML=`<div class="hint-box">${icon('help')}<p>${text}<small>С подсказкой: без XP и повышения уровня памяти.</small></p></div>`;}
function awardBadge(id){if(!journey.badges.includes(id)){journey.badges.push(id);session?.badges.push(id);}}
function recordAnswer(symbol,kind,correct,id=symbol){const xp=E.recordAnswer(stats,journey,{symbol,kind,correct,id,assisted:session.assisted,retry:session.phase==='question'&&currentQuestion().retry});session.xp+=xp;if(correct){session.correct++;session.streak++;}else session.streak=0;save();const counter=game.querySelector('.session-xp');if(counter)counter.textContent=`+${session.xp} XP`;playTone(correct);return xp;}
function feedback(correct,title,description,xp){const comment=game.querySelector('.scene-comment');if(comment){const lines=correct?['Верно! Ещё одно открытие в твоей коллекции.','Точно. Теперь попробуем применить это знание.','Отлично! В следующий раз вспомнить будет легче.']:['Посмотри на правильную пару. Ошибка — полезная подсказка.','Давай разберёмся спокойно. Следующая попытка впереди.'];comment.querySelector('p').textContent=lines[session.index%lines.length];comment.dataset.reaction=correct?'success':'support';}document.getElementById('feedback').innerHTML=`<div class="feedback ${correct?'good':'retry'}">${mascot(correct?'success':'support')}<div><strong>${title}</strong><p>${description}</p><small>${correct?(xp?`+${xp} XP`:session.assisted?'С подсказкой — сначала потренируемся':'Опыт за это задание сегодня уже получен'):'Ошибки помогают понять, к чему вернуться.'}</small></div></div>`;document.getElementById('feedback').scrollIntoView({block:'center',behavior:'auto'});}
function checkAnswer(){if(!session||session.checked||session.phase!=='question'||session.selected===null||session.selected==='')return;const q=currentQuestion(),el=bySymbol[q.symbol];if(q.kind==='audio'&&!session.heard)return;cancelSpeech();session.checked=true;const expected=q.kind==='application'?String(el.application.answer):q.symbol;const valid=q.kind==='typing'?E.validateSymbol(session.selected,expected):{correct:session.selected===expected,reason:'answer'};const xp=recordAnswer(q.symbol,q.kind,valid.correct);
  if(!q.retry&&valid.correct&&!session.assisted)session.baseCorrect++;if(!valid.correct){session.mistakes.add(q.symbol);if(!q.retry&&session.retryCount<2&&session.baseTotal-session.index>2){session.questions.push({symbol:q.symbol,kind:['audio','typing','name'].includes(q.kind)?'symbol':q.kind,retry:true});session.retryCount++;}}else if(q.retry)session.resolved.add(q.symbol);
  let explanation=q.kind==='application'?el.application.explanation:`${el.name} — ${el.symbol}. ${el.fact||`Атомный номер — ${el.number}.`}`;if(valid.reason==='case')explanation+=' Регистр важен: первая буква большая, вторая маленькая.';if(valid.reason==='latin')explanation+=' Нужны латинские буквы, даже если русские выглядят похоже.';
  game.querySelectorAll('.answer-option,.periodic-cell').forEach(button=>{button.disabled=true;const value=button.dataset.value||button.dataset.symbol;button.classList.remove('selected');button.classList.toggle('correct',value===expected);button.classList.toggle('wrong',!valid.correct&&value===session.selected);});const input=document.getElementById('symbol-input');if(input){input.disabled=true;input.classList.add(valid.correct?'correct':'wrong');}game.querySelector('[data-action="hint"]').disabled=true;feedback(valid.correct,valid.correct?'Отличное открытие!':'Посмотрим, как это устроено',explanation,xp);const button=document.getElementById('check-answer');button.dataset.action='next-question';button.textContent=session.index===session.questions.length-1?'К результатам':'Продолжить';button.disabled=false;button.focus({preventScroll:true});}
function renderPairs(){const pool=session.pairPool;game.innerHTML=`${gameHeader()}<div class="game-body"><h2 id="game-title">Соедини символ и название</h2><p class="game-subtitle" role="status">${session.left?`Теперь найди название для ${session.left}.`:session.right?`Теперь найди символ для слова «${bySymbol[session.right].name}».`:'Нажми символ слева, затем его название справа.'}</p><div class="pairs-board"><svg class="pair-lines" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">${[...session.matched].map(symbol=>{const a=pool.indexOf(symbol)*25+12.5,b=session.rightOrder.indexOf(symbol)*25+12.5;return `<path d="M42 ${a} C52 ${a} 48 ${b} 58 ${b}"/>`;}).join('')}</svg><div class="pair-column">${pool.map(symbol=>`<button class="pair-button pair-symbol ${session.matched.has(symbol)?'matched':''} ${session.left===symbol?'selected':''}" data-action="pair-left" data-symbol="${symbol}" aria-pressed="${session.left===symbol}" ${session.matched.has(symbol)?'disabled':''}>${symbol}${session.matched.has(symbol)?icon('check'):''}</button>`).join('')}</div><div class="pair-column">${session.rightOrder.map(symbol=>`<button class="pair-button ${session.matched.has(symbol)?'matched':''} ${session.right===symbol?'selected':''}" data-action="pair-right" data-symbol="${symbol}" aria-pressed="${session.right===symbol}" ${session.matched.has(symbol)?'disabled':''}>${bySymbol[symbol].name}${session.matched.has(symbol)?icon('check'):''}</button>`).join('')}</div></div><div id="feedback" role="status" aria-live="polite"></div>${mentorLine('Сначала найди знакомую пару — остальные станут проще.','thinking')}</div><div class="game-bottom"><p>${session.matched.size} из ${pool.length} пар найдено</p><button class="primary" data-action="finish" ${session.matched.size===pool.length?'':'disabled'}>К результатам ${icon('arrow')}</button></div>`;decorateSession('lab','Найди пары — соединения появятся прямо на столе.');}
function choosePair(side,symbol){if(session.matched.has(symbol))return;session[side]=symbol;if(!session.left||!session.right){renderPairs();game.querySelector(`[data-action="pair-${side==='left'?'right':'left'}"]:not([disabled])`)?.focus({preventScroll:true});return;}const left=session.left,right=session.right,correct=left===right;session.assisted=false;const xp=recordAnswer(left,'pairs',correct);if(correct){session.matched.add(left);if(!session.failedPairs.has(left))session.baseCorrect++;else session.resolved.add(left);}else{session.failedPairs.add(left);session.mistakes.add(left);}session.left=null;session.right=null;renderPairs();feedback(correct,correct?'Связь найдена!':'Эти две карточки не пара',correct?`${bySymbol[left].name} — ${left}.`:'Сначала выбери символ, затем попробуй другое название. Найденные пары останутся на месте.',xp);if(session.matched.size===session.pairPool.length){awardBadge('pairs');save();game.querySelector('[data-action="finish"]')?.focus({preventScroll:true});}else game.querySelector('[data-action="pair-left"]:not([disabled])')?.focus({preventScroll:true});}
function renderBuild(){const recipe=session.recipes[session.index];game.innerHTML=`${gameHeader()}<div class="game-body"><div class="question-meta"><span>Конструктор состава</span><span>Индексы — это подсказка</span></div><h2 id="game-title">Собери: ${recipe.name.toLowerCase()}</h2><p class="game-subtitle">Прочитай формулу и добавь нужное число атомов.</p><div class="formula-display">${recipe.formula}</div><div class="atom-workbench" aria-label="Набранные атомы">${session.atoms.length?session.atoms.map((symbol,index)=>`<button class="atom-ball atom-${symbol}" data-action="remove-atom" data-index="${index}" aria-label="Убрать атом ${symbol}" ${session.checked?'disabled':''}>${symbol}</button>`).join(''):'<span>Здесь появится твоя модель</span>'}</div><p class="tiny muted">${session.atoms.length?'Нажми на атом, чтобы убрать его.':'Нажми на элемент, чтобы добавить атом.'}</p><div class="atom-palette">${['H','O','C','N'].map(symbol=>`<button data-action="add-atom" data-symbol="${symbol}" aria-label="Добавить атом ${symbol}" ${session.checked||session.atoms.length>=6?'disabled':''}><span class="atom-ball atom-${symbol}">${symbol}</span><small>${bySymbol[symbol].name}</small><b>+</b></button>`).join('')}</div><p class="table-note">Модель показывает состав. Размеры, цвета и расположение атомов условны.</p><div id="feedback" role="status" aria-live="polite"></div></div><div class="game-bottom"><button class="text-button" data-action="clear-atoms" ${session.checked?'disabled':''}>${icon('repeat')}Начать заново</button><button class="primary" id="check-build" data-action="check-build" ${!session.atoms.length?'disabled':''}>Проверить состав ${icon('check')}</button></div>`;decorateSession('lab','Каждый индекс — подсказка о числе атомов.');}
function checkBuild(){if(session.checked||!session.atoms.length)return;const recipe=session.recipes[session.index];session.checked=true;session.assisted=false;const correct=E.recipeMatches(recipe.target,session.atoms),xp=recordAnswer(recipe.focus,'build',correct,recipe.id);if(correct){session.baseCorrect++;awardBadge('builder');}else{session.mistakes.add(recipe.focus);session.failedRecipes.add(recipe.id);}renderBuild();feedback(correct,correct?'Модель собрана!':'Проверим число атомов',recipe.explanation,xp);const button=document.getElementById('check-build');button.textContent=session.index===session.recipes.length-1?'К результатам':'Следующая модель';button.dataset.action='next-model';button.disabled=false;save();}
function finish(){if(session.finished)return;session.finished=true;cancelSpeech();session.phase='result';stats.lessons++;let bonus=0,earnedStars=0;if(session.mission){const result=E.finishMission(stats,journey,session.mission.id,session.baseCorrect,session.baseTotal);bonus=result.bonus;earnedStars=result.stars;session.xp+=bonus;awardBadge('first');if(E.MISSIONS.every(m=>journey.missions[m.id]?.completed))awardBadge('explorer');}save();const perfect=session.baseCorrect===session.baseTotal;game.innerHTML=`<div class="result-banner"><button class="close-button" data-action="close" aria-label="Закрыть результаты">×</button><div class="result-sparks" aria-hidden="true">${Array.from({length:12},(_,i)=>`<i style="--i:${i}">✦</i>`).join('')}</div>${mascot('success','result-mascot')}<div class="eyebrow">${session.mission?'Экспедиция завершена':'Тренировка завершена'}</div><h2 id="game-title">${perfect?'Вот это открытие!':'Ты продвинулся вперёд!'}</h2>${session.mission?stars(earnedStars):''}<p>${sessionTitle()}</p></div><div class="result-content"><div class="result-stats"><div><b>${session.baseCorrect}/${session.baseTotal}</b><span>самостоятельно с первой попытки</span></div><div><b>+${session.xp}</b><span>опыта${bonus?' · включая 25 за остров':''}</span></div><div><b>${session.resolved.size}</b><span>исправлений в занятии</span></div></div>${session.badges.length?`<div class="new-badges">${session.badges.map(id=>`<span>${icon(BADGES[id].icon)}Новая награда: ${BADGES[id].name}</span>`).join('')}</div>`:''}<p class="result-copy">${session.mistakes.size?'Ошибки — точки для следующего открытия. Можно вернуться к ним сейчас или продолжить путешествие.':'Теперь дай памяти небольшой перерыв. Повторение станет полезнее завтра.'}</p><div class="result-actions"><button class="primary" data-action="close">${session.mission?'Вернуться на карту':'В лабораторию'} ${icon('arrow')}</button>${session.mistakes.size?'<button class="secondary" data-action="repeat-session">Повторить сложное</button>':''}${session.mission?'<button class="secondary" data-action="next-mission">Следующий остров</button>':''}</div></div>`;if(session.mission){const chest=E.chestStatus(journey,session.mission.id);if(chest.eligible&&!chest.claimed)game.querySelector('.result-content').insertAdjacentHTML('afterbegin',`<div class="result-chest">${chestArt('small')}<div><b>Сундук острова открыт для тебя!</b><span>${chest.artifact} + ${chest.crystals} ◆</span></div><button class="primary" data-action="chest" data-id="${chest.id}">Забрать приз</button></div>`);}decorateSession('reward','Каждое открытие заслуживает места в коллекции!');focusStep();}
function renderGame(){if(session.phase==='learn')renderLearn();else if(session.phase==='pairs')renderPairs();else if(session.phase==='build')renderBuild();else if(session.phase==='question')renderQuestion();}
function russianVoice(){return 'speechSynthesis' in window?speechSynthesis.getVoices().find(voice=>/^ru(?:[-_]|$)/i.test(voice.lang)):null;}
function cancelSpeech(){speechToken++;if('speechSynthesis'in window)speechSynthesis.cancel();game.classList.remove('is-speaking');}
function speak(symbol,button,question=false,slow=false){if(!journey.speech){const status=game.querySelector('.audio-status');if(status){if(game.querySelector('[data-action="toggle-voice"]'))status.textContent='Озвучивание выключено. Включи голос или продолжай без звука.';else status.innerHTML='Озвучивание выключено. <button class="text-button" data-action="toggle-voice">Включить голос</button>';}return;}if(lastOscillator){try{lastOscillator.stop();}catch{}}const voice=russianVoice(),status=game.querySelector('.audio-status');const fail=message=>{if(status)status.textContent=message;const fallback=game.querySelector('.fallback-button');if(fallback)fallback.hidden=false;game.classList.remove('is-speaking');};if(!voice){fail('Русский голос недоступен. Можно продолжить с текстовыми заданиями.');return;}cancelSpeech();const token=speechToken;const utterance=new SpeechSynthesisUtterance(bySymbol[symbol].name);utterance.lang='ru-RU';utterance.voice=voice;utterance.rate=slow?.65:.88;let started=false;const watchdog=setTimeout(()=>{if(token===speechToken&&!started)fail('Голос не запустился. Попробуй ещё раз или перейди к символам.');},5000);utterance.onstart=()=>{if(token!==speechToken)return;started=true;clearTimeout(watchdog);game.classList.add('is-speaking');if(status)status.textContent='Слушай название…';if(question&&session){session.heard=true;game.querySelectorAll('.answer-option').forEach(option=>{option.disabled=false;});}};utterance.onend=()=>{clearTimeout(watchdog);if(token!==speechToken)return;game.classList.remove('is-speaking');if(status)status.textContent='Можно послушать ещё раз.';};utterance.onerror=()=>{clearTimeout(watchdog);if(token!==speechToken)return;fail('Не удалось воспроизвести голос. Можно перейти к символам.');if(question&&session){session.heard=false;game.querySelectorAll('.answer-option').forEach(option=>{option.disabled=true;});}};speechSynthesis.speak(utterance);}
function playTone(correct){if(!journey.sound||game.classList.contains('is-speaking'))return;try{audioContext ||= new (window.AudioContext||window.webkitAudioContext)();audioContext.resume().catch(()=>{});const oscillator=audioContext.createOscillator(),gain=audioContext.createGain(),now=audioContext.currentTime;oscillator.type='sine';oscillator.frequency.setValueAtTime(correct?523:240,now);oscillator.frequency.exponentialRampToValueAtTime(correct?784:200,now+.14);gain.gain.setValueAtTime(.055,now);gain.gain.exponentialRampToValueAtTime(.001,now+.25);oscillator.connect(gain).connect(audioContext.destination);lastOscillator=oscillator;oscillator.start(now);oscillator.stop(now+.26);}catch{journey.sound=false;renderHeader();}}
function chestArt(size='medium',opened=false){return `<span class="treasure-chest chest-${size} ${opened?'is-open':''}" aria-hidden="true"><i class="chest-glow"></i><i class="chest-lid"></i><i class="chest-base"></i><i class="chest-lock">✦</i><i class="chest-gem">◆</i></span>`;}
function decorateSession(scene,message){
  dialog.dataset.scene=scene;dialog.classList.toggle('has-full-table',session?.phase==='question'&&currentQuestion().kind==='table');
  const art=`assets/v3/${scene}-scene.png`;
  if(session?.mission&&session.phase==='learn'&&session.learnIndex===0)game.querySelector('.discovery-body')?.insertAdjacentHTML('afterbegin',`<div class="mission-goal">★ 4 из 8 без подсказки → сундук: ${E.CHESTS.find(c=>c.id===session.mission.id).crystals} ◆ и экспонат</div>`);
  game.insertAdjacentHTML('afterbegin',`<div class="session-illustration"><img src="${art}" alt="${{lab:'Рик показывает модель в яркой лаборатории',audio:'Рик слушает в наушниках за пультом',gallery:'Рик изучает экспонат через лупу',reward:'Рик открывает сундук с кристаллами'}[scene]}"><div class="scene-comment"><b>Рик</b><p>${message}</p></div></div>`);
}
function renderReferenceCard(el){
  game.innerHTML=`${gameHeader()}<div class="discovery-body reference-card"><div class="discovery-element">${tile({...el,color:el.color||'violet'})}<div><div class="eyebrow">Элемент № ${el.number}</div><h2 id="game-title">${el.name}</h2><button class="listen-button" data-action="speak" data-symbol="${el.symbol}">${icon('sound')}Послушать название</button><div class="audio-status" role="status"></div></div></div><div class="reference-facts"><div><small>Символ</small><b>${el.symbol}</b></div><div><small>Период</small><b>${el.period}</b></div><div><small>${el.group?'Группа':'Ряд'}</small><b>${el.group||(el.series==='lanthanide'?'Лантаноиды':'Актиноиды')}</b></div></div><p class="reference-family">${el.family}</p><p class="tiny muted">Семейство обозначает положение в таблице. Для сверхтяжёлых элементов многие свойства продолжают изучать.</p><div class="reference-mission"><b>Запомни пару: ${el.name} — ${el.symbol}</b><p>Три коротких задания: узнай, сопоставь, напиши.</p></div><a class="text-button" href="https://iupac.org/what-we-do/periodic-table-of-elements/" target="_blank" rel="noopener noreferrer">Источник: IUPAC ${icon('arrow')}</a></div><div class="game-bottom"><button class="text-button" data-action="close">К таблице</button><button class="primary" data-action="focus-element" data-symbol="${el.symbol}">Запомнить символ ${icon('arrow')}</button></div>`;
  decorateSession('gallery','У каждого элемента есть имя и свой адрес в таблице.');focusStep();
}
function renderTreasure(){
  const day=E.chestStatus(journey,`daily:${E.dayKey()}`),all=[...E.CHESTS.map(c=>E.chestStatus(journey,c.id)),day];
  page.innerHTML=`${warning()}<section class="page-scene-intro intro-reward"><div><div class="eyebrow">Коллекция твоих открытий</div><h1>Твои<br>сокровища</h1><p>Открой сундук. Забери экспонат. Выбери свой свет.</p><span class="crystal-total">◆ ${journey.treasure.crystals}<small>кристаллов</small></span></div></section><div class="section-heading"><h2>Пять способов получить приз</h2><span class="tiny muted">Содержимое известно заранее</span></div><div class="treasure-grid">${all.map(chest=>`<button class="treasure-card ${chest.claimed?'claimed':chest.eligible?'ready':'locked'}" data-action="chest" data-id="${chest.id}"><span class="chest-state">${chest.claimed?'Получено':chest.eligible?'Можно открыть':'Цель впереди'}</span>${chestArt('medium',chest.claimed)}<strong>${chest.title}</strong><span class="prize-line">${chest.artifact}</span><b class="crystal-prize">+${chest.crystals} ◆</b><small>${chest.condition}</small></button>`).join('')}</div><div class="section-heading"><h2>Укрась лабораторию</h2><span class="tiny muted">Оформление рамок и игрового света</span></div><div class="theme-grid">${E.THEMES.map(theme=>{const owned=journey.treasure.themes.includes(theme.id),equipped=journey.treasure.equipped===theme.id;return `<article class="theme-card theme-${theme.id}" style="--theme-color:${theme.color}"><div class="theme-swatch">${icon('atom')}<span>H</span><span>O</span></div><h3>${theme.name}</h3><button class="${equipped?'secondary':'primary'}" data-action="theme" data-id="${theme.id}" ${equipped?'disabled':''}>${equipped?'Выбрано':owned?'Применить':`Открыть за ${theme.price} ◆`}</button></article>`;}).join('')}</div><div class="section-heading"><h2>Полка экспонатов</h2></div><div class="artifact-shelf">${E.CHESTS.map(chest=>`<div class="shelf-artifact ${journey.treasure.claimed.includes(chest.id)?'owned':''}"><span class="artifact-dome">${icon(chest.icon)}</span><b>${chest.artifact}</b><small>${journey.treasure.claimed.includes(chest.id)?'В твоей коллекции':'Ждёт в сундуке острова'}</small></div>`).join('')}<div class="shelf-artifact ${journey.treasure.claimed.some(id=>id.startsWith('daily:'))?'owned':''}"><span class="artifact-dome">${icon('spark')}</span><b>Звёзды дня</b><small>Собрано: ${journey.treasure.claimed.filter(id=>id.startsWith('daily:')).length}</small></div></div>`;
}
function showChest(id){
  cancelSpeech();const chest=E.chestStatus(journey,id);if(!chest)return;activeReward=id;
  rewardContent.innerHTML=`<div class="reward-scene"><button class="close-button" data-action="close-reward" aria-label="Закрыть сундук">×</button><div class="reward-pane"><div class="eyebrow">Награда за открытие</div><h2 id="reward-title">${chest.title}</h2>${chestArt('large',chest.claimed)}<h3>${chest.artifact}</h3><p class="reward-crystals">+${chest.crystals} ◆</p><p>${chest.claimed?'Этот приз уже в твоей коллекции.':chest.eligible?'Ты выполнил условие. Пора забрать награду!':chest.condition}</p>${chest.eligible&&!chest.claimed?'<button class="primary" data-action="claim-chest">Открыть сундук</button>':`<button class="secondary" data-action="${chest.claimed?'reward-collection':'close-reward'}">${chest.claimed?'В коллекцию':'Понятно, отправляюсь'}</button>`}<small>Экспонат — на полку, кристаллы — на оформление.</small></div></div>`;
  if(!rewardDialog.open)rewardDialog.showModal();document.body.classList.add('modal-open');
}
function claimActiveChest(){
  const reward=E.claimChest(journey,activeReward);if(!reward.ok){if(!E.chestStatus(journey,activeReward)){rewardDialog.close();renderPage();toast('Начался новый день. Проверь сегодняшние цели.');}else showChest(activeReward);return;}save();
  rewardContent.querySelector('.treasure-chest').classList.add('is-open');
  rewardContent.querySelector('.reward-pane').innerHTML=`<div class="eyebrow">Новое сокровище!</div><h2 id="reward-title">${reward.artifact}</h2>${chestArt('large',true)}<p class="reward-crystals">+${reward.crystals} ◆</p><p>Теперь у тебя ${journey.treasure.crystals} кристаллов.<br>Выбери новое оформление или копи дальше.</p><div class="reward-actions"><button class="primary" data-action="reward-collection">В мою коллекцию</button><button class="secondary" data-action="close-reward">Продолжить</button></div>`;
  const previous=game.querySelector(`.result-chest [data-id="${reward.id}"]`);if(previous){previous.textContent='Получено';previous.disabled=true;}
  playTone(true);renderHeader();
}

function dispatch(button){const {action,id,mode,symbol,value,index}=button.dataset;switch(action){
  case'reward-collection':rewardDialog.close();if(dialog.open)closeGame();navigate('treasure');break;case'help':help.showModal();document.body.classList.add('modal-open');break;case'chest':showChest(id);break;case'claim-chest':claimActiveChest();break;case'close-reward':rewardDialog.close();renderPage();break;case'theme':{const result=E.equipTheme(journey,id);if(result.ok){save();renderTreasure();toast('Оформление применено.');}else toast('Пока не хватает кристаллов. Открой сундук острова.');break;}case'table-quiz':startSession({pool:button.dataset.scope==='118'?CATALOG.map(el=>el.symbol):ELEMENTS.map(el=>el.symbol),mode:'table'});break;case'focus-element':startSession({pool:[symbol],mode:'symbol',focus:true});break;case'skip-cards':session.phase='question';renderQuestion();break;case'next-mission':{const next=E.MISSIONS.find(m=>!journey.missions[m.id]?.completed)||E.MISSIONS[(E.MISSIONS.findIndex(m=>m.id===session.mission.id)+1)%E.MISSIONS.length];startMission(next.id);break;}case'mission':startMission(id);break;case'practice':startPractice(mode);break;case'review':startReview();break;
  case'glossary':help.querySelector('.glossary').open=true;help.showModal();break;case'inspect':startSession({pool:[symbol],learn:true,inspect:true});break;case'close':closeGame();break;
  case'next-card':cancelSpeech();if(session.inspect){closeGame();break;}if(session.learnIndex<session.pool.length-1)session.learnIndex++;else session.phase='question';renderGame();break;
  case'speak':speak(symbol,button);break;case'question-audio':speak(currentQuestion().symbol,button,true);break;case'toggle-voice':journey.speech=!journey.speech;if(!journey.speech)cancelSpeech();save();button.textContent=journey.speech?'Выключить голос':'Включить голос';{const status=game.querySelector('.audio-status');if(status)status.textContent=journey.speech?'Голос включён. Нажми кнопку прослушивания.':'Голос выключен. Можно продолжить без звука.';}break;case'audio-slow':speak(currentQuestion().symbol,button,true,true);break;
  case'audio-fallback':cancelSpeech();for(const question of session.questions.slice(session.index)){if(question.kind==='audio'){question.kind='symbol';delete question.choices;}}if(session.mode==='audio')session.customTitle='Практика без звука';renderQuestion();break;
  case'answer':selectAnswer(value);break;case'answer-table':selectAnswer(symbol);break;case'check':checkAnswer();break;case'hint':hint();break;
  case'next-question':session.index++;if(session.index===session.questions.length)finish();else renderQuestion();break;
  case'pair-left':choosePair('left',symbol);break;case'pair-right':choosePair('right',symbol);break;
  case'add-atom':if(!session.checked&&session.atoms.length<6){session.atoms.push(symbol);renderBuild();}break;
  case'remove-atom':if(!session.checked){session.atoms.splice(Number(index),1);renderBuild();}break;
  case'clear-atoms':session.atoms=[];renderBuild();break;case'check-build':checkBuild();break;
  case'next-model':session.index++;if(session.index===session.recipes.length)finish();else{session.checked=false;session.atoms=[];renderBuild();}break;
  case'finish':finish();break;case'repeat-session':if(session.mode==='build'){const recipes=E.RECIPES.filter(recipe=>session.failedRecipes.has(recipe.id));startSession({pool:['H','O','C','N'],mode:'build',recipes});}else startReview([...session.mistakes]);break;
  case'collection-mode':collectionMode=mode;renderCollection();break;
}}
function navigate(view){if(!['learn','practice','collection','treasure','progress'].includes(view))return;currentView=view;if(location.hash!==`#${view}`)location.hash=view;else renderPage();}
for(const span of document.querySelectorAll('[data-icon]'))span.innerHTML=icon(span.dataset.icon);
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button||button.disabled)return;if(button.dataset.view)navigate(button.dataset.view);else if(button.dataset.action)dispatch(button);});
document.addEventListener('input',event=>{if(event.target.id!=='element-search')return;const query=event.target.value.trim().toLowerCase().replace(/^йод$/,'иод');const matches=CATALOG.filter(el=>el.name.toLowerCase().includes(query)||el.symbol.toLowerCase().includes(query)||String(el.number)===query);document.getElementById('collection-results').innerHTML=matches.length?`<div class="collection-grid">${matches.map(collectionCard).join('')}</div>`:'<div class="empty-state">Такого элемента в таблице нет. Попробуй другое название.</div>';document.getElementById('collection-count').textContent=`Найдено: ${matches.length}`;});
document.addEventListener('keydown',event=>{if(!dialog.open||!session||event.repeat||event.altKey||event.ctrlKey||event.metaKey)return;if(session.phase==='question'&&!session.checked&&/^[1-4]$/.test(event.key)&&!['typing','table'].includes(currentQuestion().kind)){const option=game.querySelectorAll('.answer-option')[Number(event.key)-1];if(option&&!option.disabled){event.preventDefault();selectAnswer(option.dataset.value);}}});
dialog.addEventListener('cancel',event=>{event.preventDefault();closeGame();});
const help=document.getElementById('help-dialog');document.getElementById('help-button').addEventListener('click',()=>{help.showModal();document.body.classList.add('modal-open');});document.getElementById('close-help').addEventListener('click',()=>help.close());document.getElementById('help-start').addEventListener('click',()=>help.close());
document.getElementById('motion-toggle').addEventListener('change',event=>{journey.motion=event.target.checked;save();});
document.getElementById('voice-toggle').addEventListener('click',()=>{journey.speech=!journey.speech;if(!journey.speech)cancelSpeech();save();});
document.getElementById('sound-toggle').addEventListener('click',()=>{journey.sound=!journey.sound;save();if(journey.sound)playTone(true);});
window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(['learn','practice','collection','treasure','progress'].includes(view)){currentView=view;renderPage();}});
document.querySelectorAll('dialog').forEach(element=>element.addEventListener('close',()=>{if(!document.querySelector('dialog[open]'))document.body.classList.remove('modal-open');}));
if('speechSynthesis'in window)speechSynthesis.getVoices();
renderPage();
